import React from 'react';

export default function Navbar({ onLoginClick, isLoggedIn, studentName, setCurrentPage, currentPage }) {
  const isDashboardArea = ['Dashboard', 'Overview', 'Classes', 'Students'].includes(currentPage);

  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '15px 30px', backgroundColor: '#ffffff', borderBottom: '1px solid #e2e8f0', fontFamily: 'sans-serif' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer' }} onClick={() => setCurrentPage('Home')}>
        <div style={{ backgroundColor: '#16a34a', color: '#fff', padding: '6px 12px', borderRadius: '6px', fontWeight: 'bold', fontSize: '14px' }}>
          සිරා
        </div>
        <span style={{ fontSize: '18px', fontWeight: '700', color: '#0f172a' }}>OPEN EDUCATION</span>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: '25px' }}>
        <span style={{ cursor: 'pointer', fontSize: '14px', color: currentPage === 'Home' ? '#16a34a' : '#475569', fontWeight: '500' }} onClick={() => setCurrentPage('Home')}>Home</span>
        <span style={{ cursor: 'pointer', fontSize: '14px', color: currentPage === 'About' ? '#16a34a' : '#475569', fontWeight: '500' }} onClick={() => setCurrentPage('About')}>About</span>
        
        {isDashboardArea ? (
          <button 
            onClick={() => setCurrentPage('Home')}
            style={{ backgroundColor: '#dc2626', color: '#fff', border: 'none', padding: '8px 18px', borderRadius: '6px', cursor: 'pointer', fontWeight: '500', fontSize: '14px', transition: 'background-color 0.2s' }}
            onMouseEnter={(e) => e.currentTarget.style.backgroundColor = '#b91c1c'}
            onMouseLeave={(e) => e.currentTarget.style.backgroundColor = '#dc2626'}
          >
            Logout
          </button>
        ) : (
          isLoggedIn ? (
            <span style={{ fontSize: '14px', fontWeight: '600', color: '#0f172a' }}>🙋‍♂️ {studentName}</span>
          ) : (
            <button 
              onClick={onLoginClick}
              style={{ backgroundColor: '#16a34a', color: '#fff', border: 'none', padding: '8px 18px', borderRadius: '6px', cursor: 'pointer', fontWeight: '500', fontSize: '14px' }}
            >
              Login
            </button>
          )
        )}
      </div>
    </div>
  );
}
